'    -- Add the new .js file ',
'    apex_javascript.add_library (',
'        p_name      => ''HelloWorld'', -- Name of the Javascript file without .js extension',
'        p_directory => ''#APP_IMAGES#'', -- Path where this file is uploaded, in this case its inside Apex application directory',
'        p_version   => null );',
'    -- Assign the function to be used   ',
'    l_result.javascript_function := ''helloWorld''; -- Javascript function name present inside your file to be used here',
'    return l_result;',
'end hello_world;'))
,p_api_version=>1
,p_render_function=>'HELLO_WORLD'
,p_substitute_attributes=>true
,p_version_scn=>'1'
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
,p_files_version=>1
);
end;
