'function ajax(',
'           p_item in apex_plugin.t_page_item,',
'           p_plugin in apex_plugin.t_plugin',
'         ) return apex_plugin.t_page_item_ajax_result is',
'  l_select_list_type gt_string := p_item.attribute_01;',
