'  l_lazy_append_row_count gt_string := p_item.attribute_15;',
'',
'  l_lov apex_plugin_util.t_column_value_list;',
'  l_json gt_string;',
'  l_apex_plugin_search_logic gt_string;',
'  l_search_string gt_string;',
