prompt --application/shared_components/logic/application_processes/getempinfo
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(6585681525091042243)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_name=>'getEmpInfo'
,p_static_id=>'getempinfo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_emprow emp.ename%TYPE;',
'begin',
'   OWA_UTIL.mime_header (''text/xml'', FALSE);',
'   HTP.p (''Cache-Control: no-cache'');',
'   HTP.p (''Pragma: no-cache'');',
'   OWA_UTIL.http_header_close;',
'   HTP.prn (''<data>'');',
'   HTP.prn (''<select>'');',
'',
'/*',
'  select ename into l_emprow',
'  from emp ',
'  where empno = apex_application.g_x01;',
'  htp.p(''EMPNO: ''||l_emprow.empno||chr(10)||',
'        ''ENAME: ''||l_emprow.ename||chr(10)||',
'        ''SAL:   ''||l_emprow.sal  ||chr(10)||',
'        ''JOB:   ''||l_emprow.job); */',
'        -- HTP.prn (''<option value="'' || rec.d || ''">'' || rec.r || ''</option>'');',
'  --htp.p (l_emprow);    ',
'   FOR rec IN (select ename d, empno r--into l_emprow',
'  from emp ',
'  where DEPTNO = apex_application.g_x01)',
'   LOOP',
'      HTP.prn (''<option value="'' || rec.d || ''">'' || rec.r || ''</option>'');',
'   END LOOP;  ',
'    HTP.prn (''</select>'');',
'   HTP.prn (''</data>'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>'1'
);
end;
