prompt --application/shared_components/automations/send_mail
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(38308007374014267533)
,p_name=>'send mail'
,p_static_id=>'send-mail'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=MINUTELY;INTERVAL=2'
,p_polling_status=>'DISABLED'
,p_result_type=>'ALWAYS'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(38308007632502267535)
,p_automation_id=>wwv_flow_imp.id(38308007374014267533)
,p_name=>'Send mail every2mins'
,p_static_id=>'send-mail-every2mins'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE  ',
'--https://content.dsp.co.uk/apex/exporting-data-using-apex_data_export',
'    l_export_Blob     blob;     ',
'    l_context         apex_exec.t_context; ',
'    l_export          apex_data_export.t_export;',
'	lv_query          varchar2(32000);',
'	l_id              number;',
'	lv_tomail         varchar2(30) := ''eganjaj@gmail.com'';',
'	lv_frommail       varchar2(30) := ''eganjaj@gmail.com'';',
'	l_body            varchar2(30):= ''Emp_report'';',
'	l_filename        varchar2(30) ;',
'BEGIN',
' l_filename := ''Emp_report_''||to_char(systimestamp, ''YYYYMMDDHH24MISSFF3'');',
'    lv_query := ''select * from emp where deptno = 10'';--||:P75_ENAME;',
'    l_context := apex_exec.open_query_context(',
'        p_location    => apex_exec.c_location_local_db,',
'        p_sql_query   => lv_query );',
'    l_export := apex_data_export.export (',
'        p_context         => l_context,',
'        p_format          =>  apex_data_export.c_format_xlsx,--c_format_json,c_format_csv',
'		p_file_name       => l_filename',
'		);',
'    apex_exec.close( l_context );',
'',
'    --apex_data_export.download( p_export => l_export );',
'	',
'	 l_id := apex_mail.send(',
'        -- Valid email address to which the email is sent',
'        p_to                 => lv_tomail,',
'        -- Email address from which the email is sent',
'        p_from               => lv_frommail, ',
'        -- Static identifier string, used to identify the shared component email template',
'        p_body      => l_body,',
'        p_body_html => ''<p>''|| l_body ||''</p>'',',
'        p_subj      => ''Emp_report_subject.'');    ',
'    ',
'l_export_Blob := l_export.content_blob;',
'    -- to add multiple attachments to a single email, ',
'    -- APEX_MAIL.ADD_ATTACHMENT can be called repeatedly in a loop',
'    -- for rec in (',
'    --     select filename, blob_content, mime_type ',
'    --       from apex_application_files',
'    --      where flow_id = :APP_ID',
'    --        and filename = ''apex_logo.png''',
'    -- ) ',
'    -- loop',
'        -- this procedure adds an attachment to an email        ',
'        apex_mail.add_attachment(',
'            p_mail_id    => l_id,',
'            p_attachment => l_export_Blob,-- rec.blob_content,',
'            p_filename   => l_filename,--rec.filename,',
'            -- p_mime_type  => ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet''--rec.mime_type',
'            p_mime_type  => ''application/vnd.ms-excel''--''text/plain''',
'			);',
'    -- end loop;',
'',
'    -- Oracle APEx stores unsent email messages in a table named APEX_MAIL_QUEUE. ',
'    -- You can manually deliver mail messages stored in this queue to the ',
'    -- specified SMTP gateway by invoking the APEX_MAIL.PUSH_QUEUE procedure.',
'    apex_mail.push_queue;',
'-- end;',
' EXCEPTION',
'    when others THEN',
'        apex_exec.close( l_context );',
'        raise;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
