,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<script>',
'var v_set_intrvl = '''',',
'    v_url = '''',',
'    v_trgt_pg = '''',',
'    v_itm_nms = [],',
'    v_itm_vals = [],',
'    lSpinner$ = '''';',
'//restrict Chars',
'function restrictChars(input) {',
'    let value = input.value;',
'    let numbers = value.replace(/[^0-9]/g, "");',
'    input.value = numbers;',
'}',
'//addformat',
'function setformat(input) {',
'    const formatter = new Intl.NumberFormat(''en-IN'', {',
'        currency: ''INR'',',
'        minimumFractionDigits: 2,',
'    });',
'    var val = apex.item(input).getValue();',
'    if (val != '''') {',
'        var reslt = formatter.format(val).replace(/\D00$/, '''');',
'        apex.item(input).setValue(reslt,'''',true);',
'    }',
'    ',
'}',
'//show the loader',
'function showloader(p_btn_clk) {',
'    /*var img = document.getElementById(''loader_img'');',
'    img.style.visibility = ''visible'';*/ /*commented on 09-Dec-2021*/',
'    ',
'    f_js_chk_n_injt_loader(); // added on 09-Dec-2021',
'    ',
'    $(''.apex_wait_overlay'').css(''visibility'',''visible'');',
'	',
'    lSpinner$ = apex.util.showSpinner(); // added on 09-Dec-2021',
'	',
'    if (p_btn_clk == ''Y'') {',
'		v_set_intrvl = setInterval(f_js_clr_loader, 500);',
'	}',
'}',
'//hide the loader',
'function hideloader() {',
'    /*var img = document.getElementById(''loader_img'');',
'    img.style.visibility = ''hidden'';*//*commented on 09-Dec-2021*/',
'    ',
'    lSpinner$.remove();// added on 09-Dec-2021',
'    ',
'    $(''.apex_wait_overlay'').css(''visibility'',''hidden'');',
'}',
'',
'//redirect to raise request page',
'function f_js_rdrt_roi_pg() {',
'    apex.server.process(',
'        ''AP_MAKE_URL'', {',
'            x01: v_trgt_pg, //target_pg                ',
'            f01: v_itm_nms,',
'            f02: v_itm_vals,',
'        }, {',
'            dataType: ''text'',',
'            success: function(data) {                ',
'                v_url = data;',
'                window.location = v_url;',
'            }',
'        }',
'    );',
'}',
'',
'//to prepate url',
'function f_js_mk_url(p_pg_id, p_itm_nms, p_itm_vals) {',
'    vUrl = apex.util.makeApplicationUrl({        ',
'        pageId: p_pg_id,',
'        itemNames: p_itm_nms,',
'        itemValues: p_itm_vals',
'    });',
'	',
'	return vUrl;',
'}',
'//to set page item value',
'function f_js_setvalue(p_item_nm, p_item_val) {',
'    apex.item(p_item_nm).setValue(p_item_val);',
'}',
'//to return page item value',
'function f_js_getvalue(p_item_nm) {',
'    return apex.item(p_item_nm).getValue();',
'}',
'//for page submit',
'function f_js_pg_submit(p_btnid){',
'    //showloader(''Y'');',
'    //apex.page.submit(p_btnid);',
'    f_js_chk_n_injt_loader();',
'    apex.page.submit({',
'        request:p_btnid,    ',
'        showWait: true',
'    });',
'}',
'',
'//to restrict the string in number field',
'//Item Custom Attribute-->onkeypress="return isNumberKey(event,this.value,''Y'')"; ',
'function isNumberKey(pevt, pval, prst_decimal) {',
'alert(pevt);',
'    var charCode = (pevt.which) ? pevt.which : event.keyCode;',
'    if ((charCode == 46) && (pval != "") && (pval.indexOf(''.'') == -1) && (prst_decimal == ''N'')) {',
'        return true;',
'    } else if (charCode > 31 && (charCode < 48 || charCode > 57)) {',
'        return false;',
'    } else {',
'        return true;',
'    }',
'}',
'',
'//to set page item value in session level',
'function setsessionvalue(itemnm) {',
'    apex.server.process(',
'        "AP_SET_PG_ITM_VAL", {',
'            pageItems: "#" + itemnm',
'        }, {',
'            async: true,',
'            "dataType": "text",',
'            "success": function(pdata) {',
'                void(0);',
'            }',
'        }',
'    );',
'}',
'',
'//Use this function to set session state for application item',
'function setAppItemSessionState(AppItemName, AppItemVal) {',
'    //console.log(''AppItemVal->''+AppItemVal);',
'    apex.server.process(',
'        "AP_SET_APPITEM_VAL", {',
'            x01: AppItemName,',
'            x02: AppItemVal',
'        }, {',
'            async: false, // change here if you need sync/async',
'            "dataType": "text",',
'            "success": function(data) {',
'                void(0);',
'                console.log(data);',
'            }',
'        }',
'    );',
'}',
'//to have oracle nvl logic in javascript',
'function f_js_nvl(p_first_item, p_scnd_item) {',
'    var v_fnl_val = '''';',
'    if (p_first_item != '''') {',
'        v_fnl_val = p_first_item;',
'    } else {',
'        v_fnl_val = p_scnd_item;',
'    }',
'    return v_fnl_val;',
'}',
'//retrict letters',
'function f_js_restrt_ltr(p_input) {',
'    let value = p_input.value;',
'    let numbers = value.replace(/[^0-9]/g, "");',
'    p_input.value = numbers;',
'}',
'',
'//clear loader check interval',
'function f_js_clr_loader() { ',
'    if ($(''#APEX_ERROR_MESSAGE'').length != 0) {',
'        hideloader();',
'        clearInterval(v_set_intrvl);',
'    }',
'}',
'',
'//To display Warning message',
'function f_js_get_wrn_msg(p_coll_nm) {',
'    var v_coll_nm = p_coll_nm,',
'        v_disp_msg = '''';',
'    apex.server.process("AP_EXEC_CONV_MOD_VLD", {',
'        x01: v_coll_nm,',
'		x02: 0',
'    }, {',
'        success: function(pData) {',
'            if (pData.success === true) {',
'                for (var i = 0; i < pData.msg_coll.length; i++) {',
unistr('                     v_disp_msg += /*''\2022 ''*/i+1 +''. '' + pData.msg_coll[i].msg + ''\005Cn\005Cn'';                    '),
'                }',
'            }            ',
'            if (v_disp_msg != '''') {',
'               apex.message.alert(v_disp_msg);',
'            }',
'        },',
'        error: function(request, status, error) {',
'            apex.message.alert(request.responseText);',
'        }',
'    });',
'}',
'',
'//config bell icon button',
'function f_js_config_bell_icon (p_coll_nm, p_msg_cnt, p_js) {',
'	var v_coll_nm = '''',',
'        v_msg_cnt = p_msg_cnt,',
'		v_href_val = '''',',
'		v_cnt_html = ''<div class="count"> <div class="num" id="notification-menu_cntdiv">''+ v_msg_cnt +''</div></div>'';',
'		',
'	if(p_coll_nm != '''') {',
'        v_coll_nm = ''"'' + p_coll_nm + ''"'';',
'		v_href_val = ''javascript:f_js_get_wrn_msg(''+ v_coll_nm + '');'';	',
'		f_js_setvalue(''P0_NOTIFI_COLL_NM'', v_coll_nm.replace(/^"+|"+$/g, ''''));		',
'	} else {',
'		v_href_val = p_js;',
'		f_js_setvalue(''P0_NOTIFI_COLL_NM'', '''');',
'	}',
'	',
'	f_js_setvalue(''P0_NOTIFI_CNT'', v_msg_cnt);',
'	',
'	$(''li.t-NavigationBar-item.nav-bar-notification > a'').attr(''href'',v_href_val);',
'    if ($(''#notification-menu_cntdiv'').length == 0) {',
'        $(''li.t-NavigationBar-item.nav-bar-notification > a'').prepend(v_cnt_html);',
'    } else {',
'        $(''#notification-menu_cntdiv'').text(v_msg_cnt);',
'    }        ',
'',
'    if (v_msg_cnt > 0) {',
'        $(''.nav-bar-notification'').css(''display'','''');',
'    } else {',
'        $(''.nav-bar-notification'').css(''display'',''none'');',
'    }',
'}',
'',
'// check and inject custom loader',
'function f_js_chk_n_injt_loader() {',
'    var v_intrl;',
'',
'    //inject into spinner(default loading option in APEX) ',
'    function f_js_inject_custom_loader() {',
'		if ($(''#t_PageBody > span > span.complogo > img'').length > 0) {',
'			clearInterval(v_intrl);',
'		} else if ($(''#t_PageBody > span > span.u-Processing-spinner'').length > 0)  {',
'            var v_html = ''<img class="u-Processing-spinner" src="#APP_IMAGES#loading_img.gif" style="height: 150%;width: 150%;">'';',
'            $(''#t_PageBody > span > span.u-Processing-spinner'').prepend(v_html);',
'            $(''#t_PageBody > span > span.u-Processing-spinner'').addClass(''complogo'');',
'            $(''#t_PageBody > span > span.u-Processing-spinner'').removeClass(''u-Processing-spinner'');',
'            clearInterval(v_intrl);         ',
'        }',
'    }',
'    v_intrl = setInterval(f_js_inject_custom_loader, 100);',
'}',
'',
'//enable and disable item',
'function f_js_itm_enable_disable(p_item_nm, p_enb_disb){',
'    if (p_enb_disb == ''E'') {',
'        apex.item( p_item_nm ).enable() ;',
'    } else {',
'        apex.item( p_item_nm ).disable() ;',
'    }',
'}',
'',
'//Place the button vertically aligned at the top right corner',
'function f_js_cust_btn_position(p_class_nm) {',
'	var v_class = ''.'' + p_class_nm,		',
'		v_top_margin_incr = 5;',
'	',
'	$(v_class).each(function (index) {',
'		if (index != 0) {',
'			v_top_margin_incr = parseInt(v_top_margin_incr) + parseInt(3);',
'			v_margin_val = v_top_margin_incr + ''%'';',
'            $(''#''+this.id).css(''margin-top'',v_margin_val);			',
'		}',
'	});	',
'}',
'',
'//open inline dialog region',
'function f_js_opn_dialog(p_rgn_id,p_axn){     ',
'    if (p_axn == ''O'') {',
'        //openModal(p_rgn_id);',
'        $(''#''+ p_rgn_id).dialog(''open'');',
'',
'        $( ''#'' + p_rgn_id ).dialog( {  ',
'            closeOnEscape: false //to prevent close on clicking esc key',
'        });        ',
'    } else {',
'        closeModal(p_rgn_id);',
'    }   ',
'}',
'',
'//trunc decimal',
'function truncdecimal(p_selector,p_typ) {',
'	var n = '''';',
'    if (p_typ != '''') {       ',
'       n = apex.item(p_selector).getValue();',
'    } else {        ',
'       n = $(p_selector).text();  ',
'    }     ',
'    n = n.trim();',
'	if ((n + "").split(".")[1] == ''00'') {',
'        if (p_typ != '''') {',
'            apex.item(p_selector).setValue((n + "").split(".")[0],'''',true);            ',
'        } else {            ',
'            $(p_selector).text((n + "").split(".")[0]);',
'            console.log((n + "").split(".")[0]);',
'        }',
'	}',
'}',
'',
'//customdialog',
'function customdialog({',
'    btn1,',
'    btn2,',
'    v_msg,',
'    v_title',
'} = {}) {',
'    var buttns = {};',
'    buttns = {',
'        ''btn1'': {',
'            text: btn1,',
'            id: btn1,',
'            click: function() {',
'                rslt = btn1;',
'                $(this).dialog(''destroy'');',
'            }',
'        },',
'        ''btn2'': {',
'            text: btn2,',
'            id: btn2,',
'            click: function() {',
'                rslt = btn2;',
'                $(this).dialog(''destroy'');',
'            }',
'        }',
'    };',
'',
'    $("<div id=''customdialog'' style=''padding: 12px; font-size: 14px; width: 372px; height: 56px;''><p id=''customtxt'' style=''margin-left: 7px;''> " + v_msg + "  </p></div>").dialog({',
'        autoOpen: true,',
'        title: v_title,',
'        modal: true,',
'        buttons: buttns,',
'        close: function() {',
'            $(this).dialog(''destroy'');',
'        }',
'    });',
'}',
'',
'function setformat1(input,typ) {',
'    const formatter = new Intl.NumberFormat(''en-IN'', {',
'        currency: ''INR'',',
'        minimumFractionDigits: 2,',
'    });',
'	if (typ != '''') {',
'		var val = apex.item(input).getValue();',
'		if (val != '''') {',
'			var reslt = formatter.format(val).replace(/\D00$/, '''');',
'			apex.item(input).setValue(reslt,'''',true);',
'		}',
'	} else {',
'		$(input).each(function() {',
'			var val = $(this).text();',
'			if (val != '''') {',
'				var reslt = formatter.format(val).replace(/\D00$/, '''');',
'				$(this).text(reslt);',
'			}',
'		});',
'	}    ',
'}',
'function setdecimal(input,digit) {',
'	if (input != '''') {',
'		var val = apex.item(input).getValue();',
'         //console.log(''val ''+ val);',
'		if (val != '''') {',
'			var reslt = parseFloat(val).toFixed(digit);',
'			apex.item(input).setValue(reslt,'''',true);',
'		}',
'	}',
'}',
'-------------------------------------------------------',
'//clrchk',
'document.addEventListener(''DOMContentLoaded'', function() {',
'    var elements = document.querySelectorAll(''.clrchk'');',
'    elements.forEach(function(element) {',
'               let ldi = element.id',
'       colorchk(ldi);',
'           });',
'});',
'function colorchk(itm) //onchange="colorchk(this.id);"',
'{',
'  var rtv=  f_js_getvalue(itm);',
'     if (rtv=='''')',
'    {',
'          $x(itm).style.backgroundColor ="#ffcccb";',
'    }',
'   else',
'    { ',
'          $x(itm).style.backgroundColor =  "#DAF7A6";  ',
'    }',
'}',
' ',
'</script>'))
,p_plug_display_condition_type=>'NEVER'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
