,p_process_name=>'collection to table'
,p_static_id=>'collection-to-table'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   vid                   NUMBER;',
'   ln_stock_item_id      NUMBER;',
'',
'   CURSOR c1',
'   IS',
'      SELECT seq_id, c001, c002, c003, c004, c005, c006, c007, c008, c009,',
'             c010, c011, c012, c013, c014, c015, c016, c017, c018, c019, c020,c021,c022',
'        FROM apex_collections c',
'       WHERE c.collection_name = ''XL'';',
'BEGIN',
'   FOR rec_c1 IN c1',
'   LOOP',
'      IF rec_c1.seq_id > 1',
'      THEN',
'         BEGIN',
'         null;',
'           /*   mass_rgp_upload_files.p_ins_mass_inv_items',
'                                           (iv_item_code            => rec_c1.c002,',
'                                            iv_old_item_code        => rec_c1.c003,',
'                                            iv_item_name            => rec_c1.c004,',
'                                            iv_item_type            => ''ITEM'',---rec_c1.c005,',
'                                            id_start_date           => SYSDATE,--TO_DATE(rec_c1.c006,''DD/MM/YYYY''),',
'                                            id_end_date             => TO_DATE(rec_c1.c007,''DD/MM/YYYY''),',
'                                            iv_item_desc            => rec_c1.c008,',
'                                            iv_uom                  => rec_c1.c009,',
'                                            iv_min_qty              => rec_c1.c010,',
'                                            iv_max_qty              => rec_c1.c011,',
'                                            iv_assign_to            => ''ALL'',--rec_c1.c012,',
'                                            in_dept_id              => rec_c1.c013,',
'                                            in_grade_id             => rec_c1.c014,',
'                                            iv_raw_item_flag        => rec_c1.c017,',
'                                            iv_unit_of_measure      => rec_c1.c018,',
'                                            in_created_by           => rec_c1.c015,',
'                                            id_created_date         => SYSDATE,--TO_DATE(rec_c1.c016,''DD/MM/YYYY''),',
'                                            iv_item_category        => rec_c1.c021,',
'                                            iv_item_subcategory     => rec_c1.c022',
'                                            );',
'         END;',
'     ',
'',
'BEGIN',
'   -- IF rec_c1.c019 IS NOT NULL OR rec_c1.c020 IS NOT NULL THEN',
'            mass_rgp_upload_files.p_ins_mass_rgp_stock_ledger',
'                                          (in_item_id              => MASS_INV_ITEMS_SEQ.currval,',
'                                           iv_quantity             => rec_c1.c019,',
'                                           iv_rate                 => rec_c1.c020,',
'                                           iv_unit_of_measure      => rec_c1.c009,',
'                                           in_created_by           => rec_c1.c015,',
'                                           id_created_date         => SYSDATE,--TO_DATE(rec_c1.c016,''DD/MM/YYYY''),',
'                                           iv_warehouse_id         => :P1_WAREHOUSE_ID',
'                                          );',
'     --   END IF;   */                                       ',
'         END; ',
'      END IF;',
'     END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(7584690494858030813)
,p_internal_uid=>7584690534391030814
);
