'DECLARE',
'    l_body      CLOB;',
'    l_body_html CLOB;',
'BEGIN',
'    l_body := ''To view the content of this message, please use an HTML enabled mail client.''||utl_tcp.crlf;',
'',
'',
'',
'',
'   -- l_body_html :=:P13_body_html',
'   /* ',
'    ',
'    ''<html>',
'        <head>',
'            <style type="text/css">',
'                body{font-family: Arial, Helvetica, sans-serif;',
'                    font-size:10pt;',
'                    margin:30px;',
'                    background-color:#ffffff;}',
'',
'                span.sig{font-style:italic;',
'                    font-weight:bold;',
'                    color:#811919;}',
'             </style>',
'         </head>',
'         <body>''',
'         ',
'         */',
'         ',
'         l_body_html:=''Dear Parent,',
'We are conducting PTM (Parents Teachers Meeting) on Friday 4.2.2022 and your timeslot is from <b>4:00 - 4:10</b>. Kindly join the below link.',
'If you wish to meet any of the subject teachers, contact them and they would give you a slot on Monday, tuesday, Wednesday, Thursday.',
'Thank you and hoping to meet.''||utl_tcp.crlf;',
'    l_body_html := l_body_html  ||''<p>Thank you for your interest in the <strong>APEX_MAIL</strong> package.</p>''||utl_tcp.crlf;',
'    l_body_html := l_body_html ||''  Sincerely,<br />''||utl_tcp.crlf;',
'    l_body_html := l_body_html ||''  <span class="sig">The APEX Dev Team</span><br />''||utl_tcp.crlf;',
'	',
'	',
'	/*',
'	',
'  apex_mail.send(',
'    p_to   => ''eganjaj@gmail.com'',',
'    p_from => ''arockiyajegan.s@doyensys.com'',',
'    p_body => ''Plain text message body.'' || utl_tcp.crlf,',
'    p_subj => ''Plain text message subject.'');',
'    */',
'	apex_mail.send(',
'    p_to   => :P13_TO,  -- change to your email address',
'    p_from => :P13_from, -- change to a real senders email address',
'    p_body      => nvl(:P13_body,l_body),',
'    p_body_html =>  :P13_body_html,',
'    p_subj      => :P13_Subject);',
'  commit;',
'end;',
' '))
